//! Ventilation module isolation test: Infiltration ACH & conductance vs EnergyPlus reference.
//!
//! First dedicated ventilation test — validates that our infiltration calculations
//! match EnergyPlus output for a simple constant-infiltration model.
//!
//! # Reference Data
//!
//! Generated by EnergyPlus 25.2.0:
//! - Model: Single-zone box (6×8×2.7m), 0.5 ACH constant infiltration, no HVAC
//! - EPW: USA_CO_Golden-NREL.724666_TMY3.epw (Denver/Golden TMY3)
//! - Volume = 129.6 m³, ρ_air = 1.2 kg/m³, cp = 1000 J/(kg·K)
//! - E+ C_vent = 21.6 W/K (constant)
//! - 8760 hours (full TMY year)
//!
//! # What This Tests
//!
//! Since E+ used constant 0.5 ACH infiltration (ZoneInfiltration:DesignFlowRate with
//! constant schedule), this test validates:
//!
//! 1. **Constant ventilation schedule**: Our `ConstantVentilation(0.5).get_ach(h)` == 0.5
//!    for all 8760 hours, matching E+ infiltration_ach exactly.
//! 2. **Conductance conversion**: Our `ach_to_conductance(0.5, 129.6, 1.2, 1000.0)` == 21.6,
//!    matching E+ vent_conductance exactly.
//! 3. **Wind/stack/combined physics**: Our physics-based infiltration functions are exercised
//!    with real weather data. Since E+ used a constant model (not wind/stack), these produce
//!    different values — the test reports error statistics for diagnostic purposes, answering
//!    #918 about h_ve accuracy.
//!
//! # Acceptance Criteria (Issue #965)
//!
//! - [x] Constant ACH within 1% of E+
//! - [x] Conductance within 1% of E+
//! - [x] Report max/mean error for wind/stack/combined diagnostics
//! - [x] Test runs in <500ms

use std::fs;
use std::path::Path;
use std::time::Instant;

use fluxion::sim::ventilation::{
    ach_to_conductance, calculate_combined_infiltration_ach, calculate_stack_infiltration_ach,
    calculate_wind_infiltration_ach, ConstantVentilation, VentilationSchedule, AIR_DENSITY,
    AIR_SPECIFIC_HEAT,
};

/// Reference data row from the EnergyPlus CSV output.
///
/// CSV columns: hour(1-8760), outdoor_temp(C), wind_speed(m/s), infiltration_ach(1/h), vent_conductance(W/K)
#[derive(Debug, Clone)]
struct ReferenceRow {
    hour: usize,
    outdoor_temp: f64,
    wind_speed: f64,
    infiltration_ach: f64,
    vent_conductance: f64,
}

/// Parse the E+ reference CSV file.
///
/// Skips comment lines (starting with '#') and header row.
fn load_reference_data() -> Vec<ReferenceRow> {
    let path = Path::new("tests/reference_data/ventilation/infiltration_denver.csv");
    let content = fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("Failed to read reference data {:?}: {}", path, e));

    let mut rows = Vec::with_capacity(8760);
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = trimmed.split(',').collect();
        if parts.len() < 5 {
            continue;
        }
        // Skip header row
        if parts[0].contains("hour") {
            continue;
        }
        rows.push(ReferenceRow {
            hour: parts[0].parse::<usize>().expect("valid hour"),
            outdoor_temp: parts[1].parse::<f64>().expect("valid outdoor_temp"),
            wind_speed: parts[2].parse::<f64>().expect("valid wind_speed"),
            infiltration_ach: parts[3].parse::<f64>().expect("valid infiltration_ach"),
            vent_conductance: parts[4].parse::<f64>().expect("valid vent_conductance"),
        });
    }
    assert_eq!(rows.len(), 8760, "Expected exactly 8760 reference rows");
    rows
}

/// E+ model parameters from the reference data header.
const VOLUME: f64 = 129.6; // m³ (6×8×2.7)
const DESIGN_ACH: f64 = 0.5; // 1/h
const EXPECTED_CONDUCTANCE: f64 = 21.6; // W/K

/// Tolerance for constant-value comparisons (E+ uses exact arithmetic on constants).
const TOLERANCE_PCT: f64 = 1.0; // 1%

#[test]
fn test_constant_ach_matches_energyplus() {
    let start = Instant::now();
    let ref_data = load_reference_data();
    let vent = ConstantVentilation::new(DESIGN_ACH);

    let mut max_error_pct = 0.0_f64;
    let mut hours_exceeding_tolerance = 0usize;
    let mut sum_error_pct = 0.0_f64;

    for row in &ref_data {
        let our_ach = vent.get_ach(row.hour - 1); // 0-indexed hour
        let ep_ach = row.infiltration_ach;

        let error_pct = if ep_ach.abs() > 1e-10 {
            ((our_ach - ep_ach) / ep_ach).abs() * 100.0
        } else if our_ach.abs() > 1e-10 {
            f64::INFINITY
        } else {
            0.0
        };

        max_error_pct = max_error_pct.max(error_pct);
        sum_error_pct += error_pct;

        if error_pct > TOLERANCE_PCT {
            hours_exceeding_tolerance += 1;
        }
    }

    let mean_error_pct = sum_error_pct / ref_data.len() as f64;
    let elapsed = start.elapsed();

    eprintln!("\n=== Constant ACH vs E+ ===");
    eprintln!("Hours tested:    {}", ref_data.len());
    eprintln!("Max error:       {max_error_pct:.4}%");
    eprintln!("Mean error:      {mean_error_pct:.6}%");
    eprintln!("Hours > {TOLERANCE_PCT}%:  {hours_exceeding_tolerance}");
    eprintln!("Elapsed:         {elapsed:.2?}");

    assert!(
        max_error_pct <= TOLERANCE_PCT,
        "Constant ACH exceeds {TOLERANCE_PCT}% tolerance: max error = {max_error_pct:.4}%"
    );
    assert_eq!(
        hours_exceeding_tolerance, 0,
        "No hours should exceed tolerance for constant ventilation"
    );
}

#[test]
fn test_conductance_matches_energyplus() {
    let start = Instant::now();
    let ref_data = load_reference_data();

    let mut max_error_pct = 0.0_f64;
    let mut hours_exceeding_tolerance = 0usize;
    let mut sum_error_pct = 0.0_f64;

    for row in &ref_data {
        // Use the same parameters as E+: ach=0.5, volume=129.6, rho=1.2, cp=1000
        let our_cond = ach_to_conductance(DESIGN_ACH, VOLUME, AIR_DENSITY, AIR_SPECIFIC_HEAT)
            .get::<uom::si::thermal_conductance::watt_per_kelvin>();
        let ep_cond = row.vent_conductance;

        let error_pct = if ep_cond.abs() > 1e-10 {
            ((our_cond - ep_cond) / ep_cond).abs() * 100.0
        } else {
            0.0
        };

        max_error_pct = max_error_pct.max(error_pct);
        sum_error_pct += error_pct;

        if error_pct > TOLERANCE_PCT {
            hours_exceeding_tolerance += 1;
        }
    }

    let mean_error_pct = sum_error_pct / ref_data.len() as f64;
    let elapsed = start.elapsed();

    // Verify the analytical result: (0.5 * 129.6 * 1.2 * 1000) / 3600 = 21.6
    let computed = ach_to_conductance(DESIGN_ACH, VOLUME, AIR_DENSITY, AIR_SPECIFIC_HEAT)
        .get::<uom::si::thermal_conductance::watt_per_kelvin>();
    assert!(
        (computed - EXPECTED_CONDUCTANCE).abs() < 1e-10,
        "Conductance formula verification: expected {EXPECTED_CONDUCTANCE}, got {computed}"
    );

    eprintln!("\n=== Conductance vs E+ ===");
    eprintln!("Hours tested:    {}", ref_data.len());
    eprintln!("Computed value:  {computed:.6} W/K");
    eprintln!("E+ value:        {EXPECTED_CONDUCTANCE} W/K");
    eprintln!("Max error:       {max_error_pct:.4}%");
    eprintln!("Mean error:      {mean_error_pct:.6}%");
    eprintln!("Hours > {TOLERANCE_PCT}%:  {hours_exceeding_tolerance}");
    eprintln!("Elapsed:         {elapsed:.2?}");

    assert!(
        max_error_pct <= TOLERANCE_PCT,
        "Conductance exceeds {TOLERANCE_PCT}% tolerance: max error = {max_error_pct:.4}%"
    );
}

#[test]
fn test_wind_infiltration_diagnostics() {
    // Diagnostic test: exercise wind infiltration with real weather data.
    //
    // Since E+ used constant infiltration (not wind-dependent), our wind-based
    // ACH will NOT match E+ infiltration_ach. This test reports the discrepancy
    // to answer #918 about h_ve accuracy.
    let start = Instant::now();
    let ref_data = load_reference_data();

    // Building parameters from the E+ model
    let building_height = 2.7; // m (single-story zone height)
    let shielding_factor = 0.0; // exposed site (NREL)

    let mut wind_ach_values = Vec::with_capacity(8760);
    let mut max_wind_ach = 0.0_f64;
    let mut sum_wind_ach = 0.0_f64;

    for row in &ref_data {
        let wind_ach =
            calculate_wind_infiltration_ach(row.wind_speed, building_height, shielding_factor);
        assert!(
            wind_ach >= 0.0,
            "Wind ACH must be non-negative at hour {}",
            row.hour
        );
        max_wind_ach = max_wind_ach.max(wind_ach);
        sum_wind_ach += wind_ach;
        wind_ach_values.push(wind_ach);
    }

    let mean_wind_ach = sum_wind_ach / 8760.0;
    let elapsed = start.elapsed();

    // Error vs E+ constant 0.5 ACH (diagnostic — not a pass/fail criterion)
    let max_error_vs_ep = wind_ach_values
        .iter()
        .map(|&v| ((v - DESIGN_ACH) / DESIGN_ACH).abs() * 100.0)
        .fold(0.0_f64, f64::max);
    let mean_error_vs_ep = wind_ach_values
        .iter()
        .map(|&v| ((v - DESIGN_ACH) / DESIGN_ACH).abs() * 100.0)
        .sum::<f64>()
        / 8760.0;

    eprintln!("\n=== Wind Infiltration Diagnostics (#918) ===");
    eprintln!("Building height: {building_height} m");
    eprintln!("Shielding:       {shielding_factor}");
    eprintln!("Mean wind ACH:   {mean_wind_ach:.4} 1/h");
    eprintln!("Max wind ACH:    {max_wind_ach:.4} 1/h");
    eprintln!(
        "Min wind ACH:    {:.4} 1/h",
        wind_ach_values
            .iter()
            .cloned()
            .fold(f64::INFINITY, f64::min)
    );
    eprintln!("E+ constant ACH: {DESIGN_ACH} 1/h");
    eprintln!("Max error vs E+: {max_error_vs_ep:.1}%");
    eprintln!("Mean error vs E+:{mean_error_vs_ep:.1}%");
    eprintln!("Elapsed:         {elapsed:.2?}");

    // Physics sanity checks (must pass):
    // Wind ACH should be monotonically increasing with wind speed
    for row in &ref_data {
        let ach =
            calculate_wind_infiltration_ach(row.wind_speed, building_height, shielding_factor);
        // Zero wind → zero ACH
        if row.wind_speed == 0.0 {
            assert!(
                ach < 1e-10,
                "Zero wind speed must produce zero wind ACH at hour {}",
                row.hour
            );
        }
    }

    // Higher wind speed must produce higher ACH (for same height/shielding)
    let ach_low = calculate_wind_infiltration_ach(2.0, building_height, shielding_factor);
    let ach_high = calculate_wind_infiltration_ach(8.0, building_height, shielding_factor);
    assert!(
        ach_high > ach_low,
        "Wind ACH must increase with wind speed: {ach_high} !> {ach_low}"
    );

    assert!(
        elapsed.as_millis() < 500,
        "Test must run in <500ms: {:?}",
        elapsed
    );
}

#[test]
fn test_stack_infiltration_diagnostics() {
    // Diagnostic test: exercise stack infiltration with real weather data.
    //
    // E+ used constant infiltration, so stack ACH won't match. We verify
    // physical consistency and report error statistics.
    let start = Instant::now();
    let ref_data = load_reference_data();

    // For stack effect we need indoor temperature. E+ model has no HVAC
    // (free-floating), so indoor temp ≈ outdoor temp for an uninsulated box
    // with 0.5 ACH. Use a small ΔT to estimate the stack contribution.
    let height_diff = 2.7; // m (inlet-to-outlet vertical distance)
    let opening_area = 1.0; // m² (effective opening area)
    let indoor_temp = 20.0; // °C (assume near-equilibrium in free-floating)

    let mut stack_ach_values = Vec::with_capacity(8760);
    let mut nonzero_count = 0usize;

    for row in &ref_data {
        let stack_ach = calculate_stack_infiltration_ach(
            indoor_temp,
            row.outdoor_temp,
            height_diff,
            opening_area,
            VOLUME,
        );
        assert!(
            stack_ach >= 0.0,
            "Stack ACH must be non-negative at hour {}",
            row.hour
        );
        if stack_ach > 1e-10 {
            nonzero_count += 1;
        }
        stack_ach_values.push(stack_ach);
    }

    let mean_stack_ach = stack_ach_values.iter().sum::<f64>() / 8760.0;
    let max_stack_ach = stack_ach_values.iter().cloned().fold(0.0_f64, f64::max);
    let elapsed = start.elapsed();

    eprintln!("\n=== Stack Infiltration Diagnostics (#918) ===");
    eprintln!("Indoor temp:     {indoor_temp} °C (assumed)");
    eprintln!("Height diff:     {height_diff} m");
    eprintln!("Opening area:    {opening_area} m²");
    eprintln!("Mean stack ACH:  {mean_stack_ach:.4} 1/h");
    eprintln!("Max stack ACH:   {max_stack_ach:.4} 1/h");
    eprintln!("Nonzero hours:   {nonzero_count}/8760");
    eprintln!("E+ constant ACH: {DESIGN_ACH} 1/h");
    eprintln!("Elapsed:         {elapsed:.2?}");

    // Physics sanity: equal temperatures → zero stack ACH
    let zero_dt = calculate_stack_infiltration_ach(20.0, 20.0, height_diff, opening_area, VOLUME);
    assert!(
        zero_dt.abs() < 1e-10,
        "Zero ΔT must produce zero stack ACH, got {zero_dt}"
    );

    // Larger ΔT → larger stack ACH
    let small_dt = calculate_stack_infiltration_ach(22.0, 20.0, height_diff, opening_area, VOLUME);
    let large_dt = calculate_stack_infiltration_ach(30.0, 20.0, height_diff, opening_area, VOLUME);
    assert!(
        large_dt > small_dt,
        "Larger ΔT must produce larger stack ACH: {large_dt} !> {small_dt}"
    );

    assert!(
        elapsed.as_millis() < 500,
        "Test must run in <500ms: {:?}",
        elapsed
    );
}

#[test]
fn test_combined_infiltration_diagnostics() {
    // Diagnostic test: exercise combined infiltration with real weather data.
    //
    // E+ used constant infiltration. Our combined model adds wind + stack.
    // Reports overall accuracy vs E+ constant model.
    let start = Instant::now();
    let ref_data = load_reference_data();

    let building_height = 2.7;
    let height_diff = 2.7;
    let opening_area = 1.0;
    let shielding_factor = 0.0;
    let indoor_temp = 20.0;

    let mut max_error_pct = 0.0_f64;
    let mut sum_error_pct = 0.0_f64;
    let mut hours_exceeding = 0usize;
    let mut combined_ach_sum = 0.0_f64;

    for row in &ref_data {
        let combined = calculate_combined_infiltration_ach(
            row.outdoor_temp,
            indoor_temp,
            row.wind_speed,
            height_diff,
            opening_area,
            VOLUME,
            shielding_factor,
        );

        assert!(
            combined >= 0.0,
            "Combined ACH must be non-negative at hour {}",
            row.hour
        );

        combined_ach_sum += combined;

        let error_pct = if row.infiltration_ach.abs() > 1e-10 {
            ((combined - row.infiltration_ach) / row.infiltration_ach).abs() * 100.0
        } else {
            0.0
        };

        max_error_pct = max_error_pct.max(error_pct);
        sum_error_pct += error_pct;
        if error_pct > TOLERANCE_PCT {
            hours_exceeding += 1;
        }
    }

    let mean_combined_ach = combined_ach_sum / 8760.0;
    let mean_error_pct = sum_error_pct / 8760.0;
    let elapsed = start.elapsed();

    eprintln!("\n=== Combined Infiltration Diagnostics (#918) ===");
    eprintln!("Mean combined:   {mean_combined_ach:.4} 1/h");
    eprintln!("E+ constant:     {DESIGN_ACH} 1/h");
    eprintln!("Max error vs E+: {max_error_pct:.1}%");
    eprintln!("Mean error vs E+:{mean_error_pct:.1}%");
    eprintln!("Hours > {TOLERANCE_PCT}%:  {hours_exceeding}/8760");
    eprintln!("NOTE: E+ used constant infiltration; combined is physics-based (wind+stack).");
    eprintln!("      Error is expected. This diagnostic informs #918 h_ve accuracy.");
    eprintln!("Elapsed:         {elapsed:.2?}");

    // The combined model will NOT match E+ constant — this is expected.
    // Physics check: combined must equal wind + stack individually
    for row in &ref_data {
        let wind =
            calculate_wind_infiltration_ach(row.wind_speed, building_height, shielding_factor);
        let stack = calculate_stack_infiltration_ach(
            indoor_temp,
            row.outdoor_temp,
            height_diff,
            opening_area,
            VOLUME,
        );
        let combined = calculate_combined_infiltration_ach(
            row.outdoor_temp,
            indoor_temp,
            row.wind_speed,
            height_diff,
            opening_area,
            VOLUME,
            shielding_factor,
        );
        let expected = (wind + stack).max(0.0);
        assert!(
            (combined - expected).abs() < 1e-10,
            "Combined must equal wind + stack at hour {}: got {combined}, expected {expected}",
            row.hour
        );
    }

    assert!(
        elapsed.as_millis() < 500,
        "Test must run in <500ms: {:?}",
        elapsed
    );
}

#[test]
fn test_ach_to_conductance_formula() {
    // Verify the conductance formula analytically:
    //   C_vent = (ACH × V × ρ × cp) / 3600
    // For E+ parameters: (0.5 × 129.6 × 1.2 × 1000) / 3600 = 21.6
    let expected = (DESIGN_ACH * VOLUME * AIR_DENSITY * AIR_SPECIFIC_HEAT) / 3600.0;
    assert!(
        (expected - EXPECTED_CONDUCTANCE).abs() < 1e-10,
        "Analytical verification: expected {EXPECTED_CONDUCTANCE}, computed {expected}"
    );

    let computed = ach_to_conductance(DESIGN_ACH, VOLUME, AIR_DENSITY, AIR_SPECIFIC_HEAT)
        .get::<uom::si::thermal_conductance::watt_per_kelvin>();
    assert!(
        (computed - expected).abs() < 1e-10,
        "ach_to_conductance: expected {expected}, got {computed}"
    );

    // Scaling: double ACH → double conductance
    let c1 = ach_to_conductance(0.5, VOLUME, AIR_DENSITY, AIR_SPECIFIC_HEAT)
        .get::<uom::si::thermal_conductance::watt_per_kelvin>();
    let c2 = ach_to_conductance(1.0, VOLUME, AIR_DENSITY, AIR_SPECIFIC_HEAT)
        .get::<uom::si::thermal_conductance::watt_per_kelvin>();
    assert!(
        (c2 - 2.0 * c1).abs() < 1e-10,
        "Doubling ACH must double conductance"
    );

    // Zero ACH → zero conductance
    assert_eq!(
        ach_to_conductance(0.0, VOLUME, AIR_DENSITY, AIR_SPECIFIC_HEAT)
            .get::<uom::si::thermal_conductance::watt_per_kelvin>(),
        0.0
    );
}
